lfmoord hebben gepleegd. Zijn zoektocht leidt naar een computerspel waarin drie zonnen het leven onvoorspelbaar maken. Wat een raadselachtige virtuele wereld lijkt, blijkt verbonden met gebeurtenissen buiten de aarde en met keuzes die de toekomst van de mensheid raken.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1355176/het-drielichamenprobleem.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/1355176/het-drielichamenprobleem.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"004c2bb56ad7108b651d627fa8746e0ee5d6ec8b2f255710a1c79f698d6e836a"}]}},{"relation":"editions","ref":"edition:9789026623554","key":{"id":976200102},"before":null,"after":{"work_id":921100026,"title":"De wereld achter de kastdeur","isbn_13":"9789026623554","isbn_10":null,"language":"nld","publisher":"VBK Media","open_library_edition_id":null,"id":976200102}},{"relation":"catalog_edition_metadata","ref":"metadata:9789026623554","key":{"edition_id":"@edition:9789026623554"},"before":null,"after":{"edition_id":"@edition:9789026623554","work_id":921100026,"bound_author_id":921300021,"bound_title":"De wereld achter de kastdeur","bound_language":"nld","bound_isbn13":"9789026623554","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000531155_De_wereld_achter_de_kastdeur_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1400062/de-wereld-achter-de-kastdeur.html","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-01-20261101","evidence":[{"url":"https://metadata.isbn.nl/1400062/de-wereld-achter-de-kastdeur.html","checkedAt":"2026-11-01","sha256":"cf3de7a5376efa946459ad39bd7d473481f784cf2de6cb182ef76c7e28